/**
 * Shared contracts for the SportsHub AI assistant tools.
 *
 * Every tool returns the same envelope so the orchestrator (and any
 * grader) can distinguish "no results" from "unsupported filter" from
 * "the database failed" — a tool error must never be paraphrased by the
 * model as "there are no venues/reviews".
 *
 * Provenance kinds (field-level, see docs/ai-assistant.md §Truth model):
 * - imported:          taken from an external source (Google Maps listing)
 * - owner_verified:    supplied/maintained by the venue owner in SportsHub
 * - platform_reference: generated by the platform as reference data
 *                      (e.g. price rules derived from a sport price band)
 * - default_generated: filled from platform defaults, NOT verified
 * - unknown:           no basis recorded
 */
export type ProvenanceKind =
  | "imported"
  | "owner_verified"
  | "platform_reference"
  | "default_generated"
  | "unknown";

export type ToolStatus = "ok" | "empty" | "partial" | "error";

export interface ToolError {
  code: string;
  message: string;
}

export interface ToolEnvelope<T> {
  status: ToolStatus;
  data: T | null;
  /** The filters/arguments actually applied (after normalization). */
  appliedFilters: Record<string, unknown>;
  /** ISO instant when the tool read its data. */
  checkedAt: string;
  /** When the underlying data was last known to change, if knowable. */
  dataAsOf: string | null;
  warnings: string[];
  /** Provenance per data group, e.g. { prices: "platform_reference" }. */
  provenance: Record<string, ProvenanceKind>;
  /** Evidence ids (from search_review_evidence) this result relies on. */
  evidenceRefs: string[];
  error: ToolError | null;
}

export function okEnvelope<T>(
  data: T,
  opts: Partial<Omit<ToolEnvelope<T>, "status" | "data" | "error">> & { status?: ToolStatus } = {},
): ToolEnvelope<T> {
  return {
    status: opts.status ?? "ok",
    data,
    appliedFilters: opts.appliedFilters ?? {},
    checkedAt: opts.checkedAt ?? new Date().toISOString(),
    dataAsOf: opts.dataAsOf ?? null,
    warnings: opts.warnings ?? [],
    provenance: opts.provenance ?? {},
    evidenceRefs: opts.evidenceRefs ?? [],
    error: null,
  };
}

export function errorEnvelope(
  code: string,
  message: string,
  opts: Partial<Omit<ToolEnvelope<never>, "status" | "data" | "error">> = {},
): ToolEnvelope<never> {
  return {
    status: "error",
    data: null,
    appliedFilters: opts.appliedFilters ?? {},
    checkedAt: opts.checkedAt ?? new Date().toISOString(),
    dataAsOf: opts.dataAsOf ?? null,
    warnings: opts.warnings ?? [],
    provenance: opts.provenance ?? {},
    evidenceRefs: opts.evidenceRefs ?? [],
    error: { code, message },
  };
}

/** Stable error codes shared by tools, orchestrator and graders. */
export const ToolErrorCode = {
  InvalidInput: "INVALID_INPUT",
  NotFound: "NOT_FOUND",
  NotPublic: "NOT_PUBLIC",
  DbError: "DB_ERROR",
  Timeout: "TOOL_TIMEOUT",
  UnsupportedTimeFilter: "UNSUPPORTED_TIME_FILTER",
  UnsupportedFilter: "UNSUPPORTED_FILTER",
  BudgetExhausted: "BUDGET_EXHAUSTED",
  PriceUnavailable: "PRICE_UNAVAILABLE",
  SlotUnavailable: "SLOT_UNAVAILABLE",
  ConfigMissing: "CONFIG_MISSING",
} as const;

/**
 * Execution context handed to every tool. `db` is injectable so tools can
 * be integration-tested against a throwaway database; `now` is injectable
 * so time-dependent behaviour is testable under a fixed clock; `budget`
 * counts EVERY execution, including the sub-calls a composite tool makes,
 * so a composite cannot launder unlimited work past the request budget.
 */
export interface ToolContext {
  db: import("@prisma/client").PrismaClient;
  now: Date;
  budget: BudgetCounter;
  /** Hard per-tool deadline in ms (enforced by the orchestrator too). */
  timeoutMs: number;
}

export class BudgetCounter {
  private used = 0;
  constructor(private readonly max: number) {}
  /** Consume n executions; returns false when the budget is exhausted. */
  consume(n = 1): boolean {
    if (this.used + n > this.max) return false;
    this.used += n;
    return true;
  }
  get usedCount(): number {
    return this.used;
  }
  get remaining(): number {
    return Math.max(0, this.max - this.used);
  }
  get limit(): number {
    return this.max;
  }
}

/** The platform availability is a demo schedule: no live owner calendar
 * integration exists, and every surface must say so. */
export const AVAILABILITY_SCOPE = "sportsHub_demo_schedule";
export const AVAILABILITY_WARNING =
  "Lịch và giá lấy từ lịch mô phỏng trong SportsHub (giá tham chiếu của nền tảng, chưa được chủ sân xác nhận); sân ngoài thực tế có thể khác.";

/** Provenance set for a venue, derived from its recorded source. Honest
 * by construction: imported (Google) venues got their facilities,
 * amenities and hours from platform defaults/normalization, and their
 * prices from the platform's per-sport reference band. */
export function venueProvenance(source: string): Record<string, ProvenanceKind> {
  switch (source) {
    case "google":
      return {
        identity: "imported",
        address: "imported",
        coordinates: "imported",
        googleRating: "imported",
        googleReviews: "imported",
        facilities: "default_generated",
        amenities: "default_generated",
        operatingHours: "imported",
        prices: "platform_reference",
        cancellationPolicy: "platform_reference",
        venueType: "default_generated",
      };
    case "owner":
      return {
        identity: "owner_verified",
        address: "owner_verified",
        coordinates: "owner_verified",
        googleRating: "unknown",
        googleReviews: "unknown",
        facilities: "owner_verified",
        amenities: "owner_verified",
        operatingHours: "owner_verified",
        prices: "owner_verified",
        cancellationPolicy: "owner_verified",
        venueType: "owner_verified",
      };
    default:
      return {
        identity: "platform_reference",
        address: "platform_reference",
        coordinates: "platform_reference",
        googleRating: "unknown",
        googleReviews: "unknown",
        facilities: "platform_reference",
        amenities: "platform_reference",
        operatingHours: "platform_reference",
        prices: "platform_reference",
        cancellationPolicy: "platform_reference",
        venueType: "platform_reference",
      };
  }
}

/** What `verified` may NOT be read as: for imported venues it only marks
 * the import, the listing is unclaimed by any real owner. */
export function verificationStatus(source: string): string {
  switch (source) {
    case "google":
      return "imported_listing_not_owner_claimed";
    case "owner":
      return "owner_managed";
    default:
      return "platform_sample";
  }
}
